// Feature 4: Printable Terminal Report Sheet page (parents).
// Shows the standard sheet for one child and term, fitted to one A4 page
// with the school's print margins. The PDF download button lives on the
// results page; the PDF version is generated by app/api/results/report-sheet.

import { Suspense } from "react";
import Link from "next/link";
import type { Metadata } from "next";
import { TERM_LABELS, type TermLabel } from "@/lib/results/types";
import {
  canParentView,
  getChildren,
  getClassStanding,
  getCurrentSession,
  getTermAvailability,
  getTermResult,
} from "@/lib/results/getResults";
import ReportSheet from "./ReportSheet";
import PrintButton from "./PrintButton";
import { reportSheetFileName } from "@/lib/results/reportSheetFileName";
import { requireRole } from "@/lib/auth/session";

const NAVY = "#12264F";

export const metadata: Metadata = {
  title: "Terminal Report Sheet",
};

// One A4 portrait page on paper. On screen we keep a preview style.
const A4_PRINT_CSS = `
@page { size: A4 portrait; margin: 13mm 12mm; }
@media print {
  body { background: #ffffff !important; }
  .print-hide { display: none !important; }
  .report-sheet { border: 0 !important; padding: 0 !important; }
}
`;

function first(v: string | string[] | undefined): string | undefined {
  return Array.isArray(v) ? v[0] : v;
}

function parseTerm(v: string | undefined): TermLabel {
  return (TERM_LABELS as readonly string[]).includes(v ?? "")
    ? (v as TermLabel)
    : "First";
}

export default function ReportSheetPage(
  props: PageProps<"/dashboard/academics/results/report-sheet">,
) {
  return (
    <main className="mx-auto w-full max-w-3xl px-4 pb-16 pt-6 sm:px-6 print:max-w-none print:p-0">
      <style
        dangerouslySetInnerHTML={{ __html: A4_PRINT_CSS }}
        href="a4-print"
        precedence="default"
      />

      <Suspense fallback={<p className="text-sm text-slate-500">Loading report sheet…</p>}>
        <ReportSheetPanel searchParams={props.searchParams} />
      </Suspense>
    </main>
  );
}

async function ReportSheetPanel({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // ---------------------------------------------------------------------
  const gate = await requireRole("parent", "admin");
  if (gate.status === "forbidden") {
    return <main className="p-8">You do not have permission to view results.</main>;
  }
  const parent = gate.user;
  const parentChildren = await getChildren(parent.id);
  if (parentChildren.length === 0) {
    return <Blocker tone="info" title="No children are linked to this account.">Contact the school office to link your child to your portal account.</Blocker>;
  }
  const session = await getCurrentSession();
  const url = await searchParams;

  const requestedChildId = first(url.child) ?? parentChildren[0]?.id ?? "";
  const term = parseTerm(first(url.term));

  const ownsChild = await canParentView(parent.id, requestedChildId);
  const child = parentChildren.find((c) => c.id === requestedChildId);

  if (!ownsChild) {
    return (
      <Blocker tone="warn" title="You can only view results for your own child.">
        Choose one of your children on the Results page.
      </Blocker>
    );
  }

  const availability = await getTermAvailability(requestedChildId, term, session);
  const result = availability === "ready" ? await getTermResult(requestedChildId, term, session) : null;

  if (availability !== "ready" || !result || !result.published) {
    const title = availability === "no-scores" ? "No scores are available for this term yet." : availability === "no-calendar" ? "Term details are not available yet." : "Results for this term have not been published yet.";
    return (
      <Blocker tone="info" title={title}>
        {availability === "no-scores" ? "The school has not entered scores for this term." : availability === "no-calendar" ? "The school calendar has not been set up for this term." : "We will email you when they are ready. There is nothing you need to do."}
      </Blocker>
    );
  }

  const standing = await getClassStanding(result);

  return (
    <>
      <div className="print-hide mb-4 flex flex-wrap items-center justify-between gap-3">
        <h1
          className="text-xl font-bold font-[family-name:var(--font-poppins)]"
          style={{ color: NAVY }}
        >
          Report Sheet (preview)
        </h1>
        <div className="flex flex-wrap items-center gap-2">
          <Link
            href="/dashboard/academics/results"
            prefetch={false}
            className="rounded-xl border-2 border-[#12264F] bg-white px-5 py-3 text-base font-semibold text-[#12264F] hover:bg-slate-50 focus-visible:outline-2 focus-visible:outline-[#C9A227]"
          >
            Back to results
          </Link>
          <a
            href={`/api/results/report-sheet?${new URLSearchParams({
              child: first(url.child) ?? "",
              term: parseTerm(first(url.term)),
            }).toString()}`}
            download={reportSheetFileName(
              parentChildren.find((c) => c.id === requestedChildId)?.name ?? "",
              term,
            )}
            type="application/pdf"
            className="rounded-xl bg-[#12264F] px-5 py-3 text-base font-semibold text-white shadow-sm hover:bg-[#0d1b3a] focus-visible:outline-2 focus-visible:outline-[#C9A227]"
          >
            Download Report Sheet
          </a>
          <PrintButton />
        </div>
      </div>

      <ReportSheet
        studentName={child?.name ?? ""}
        className={result.className}
        admissionNumber={child?.admissionNumber ?? ""}
        term={term}
        session={session}
        result={result}
        standing={standing}
      />

      {child && child.className !== result.className ? <p className="print-hide mt-3 text-sm text-slate-600">This student has since moved classes. This report shows the class recorded for {term} term.</p> : null}

      <p className="print-hide mt-4 text-xs text-slate-500">
        Scores and attendance are read from the school database.
      </p>
    </>
  );
}

function Blocker({
  title,
  children,
  tone,
}: {
  title: string;
  children: React.ReactNode;
  tone: "info" | "warn";
}) {
  return (
    <div
      className={
        tone === "warn"
          ? "rounded-2xl border-2 border-red-200 bg-red-50 p-4"
          : "rounded-2xl border-2 border-blue-200 bg-blue-50 p-4"
      }
    >
      <p
        className={`font-semibold font-[family-name:var(--font-poppins)] ${
          tone === "warn" ? "text-red-800" : "text-blue-900"
        }`}
      >
        {title}
      </p>
      <p
        className={`mt-1 text-sm ${tone === "warn" ? "text-red-700" : "text-blue-800"}`}
      >
        {children}
      </p>
    </div>
  );
}
